pub mod render {
    //! Rendering: the widget renderer, frame buffers, backends, cursors, and
    //! motion.

    /// The trait implemented by renderers.
    pub trait RenderBackend {
        /// Flush output to the terminal.
        fn flush(&mut self) -> crate::error::Result<()>;

        /// Move the hidden terminal cursor to the primary soft cursor, where input
        /// methods and screen magnifiers look for it. `None` leaves it in place.
        fn park_cursor(&mut self, _location: Option<Point>) -> crate::error::Result<()> {}

        /// Reset the backend to a clean state.
        fn reset(&mut self) -> crate::error::Result<()> {}

        /// Shift characters within a line starting at the location.
        /// Positive counts insert blanks and shift right, negative counts delete
        /// and shift left.
        fn shift_chars(&mut self, _loc: Point, _count: i32) -> crate::error::Result<()> {}

        /// Shift lines within the inclusive (top..=bottom) region.
        /// Positive counts shift content down, negative counts shift content up.
        fn shift_lines(
            &mut self,
            _top: u32,
            _bottom: u32,
            _count: i32,
        ) -> crate::error::Result<()> {
        }

        /// Apply a style to the following text output
        fn style(&mut self, style: &ResolvedStyle) -> crate::error::Result<()>;

        /// Return true if the backend can shift characters within a line.
        fn supports_char_shift(&self) -> bool {}

        /// Return true if the backend can shift lines within a region.
        fn supports_line_shift(&self) -> bool {}

        /// Output text to screen. This method is used for all text output.
        fn text(&mut self, loc: Point, txt: &str) -> crate::error::Result<()>;
    }

    /// A terminal cell with glyph and style.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Cell {
        /// Base glyph character.
        pub ch: char,
        /// Additional grapheme characters stored with the base glyph.
        pub suffix: String,
        /// ResolvedStyle applied to the cell.
        pub style: ResolvedStyle,
        /// True when this cell continues a wide glyph from the previous column.
        pub continuation: bool,
    }

    impl Cell {
        /// Return this cell's rendered text.
        pub fn rendered_text(&self) -> String;
    }

    /// Global motion settings.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct MotionSettings {
        /// Whether cells move. With `false`, every cell stays at rest.
        pub enabled: bool,
        /// Most samples a second of motion that changes continuously.
        pub max_fps: u32,
        /// Time without input after which repeating motion pauses at rest.
        pub idle_pause: Duration,
    }

    /// A render backend that discards all output.
    ///
    /// Rendering through this backend refreshes the terminal buffer without
    /// producing user-visible output, so callers can inspect the buffer directly.
    #[derive(Default)]
    pub struct NopBackend;

    impl NopBackend {
        /// Construct a no-op backend.
        pub fn new() -> Self;
    }

    impl RenderBackend for NopBackend {}

    /// A renderer that only renders to a specific rectangle within the target
    /// terminal buffer.
    pub struct Render<'a> {/* private fields */}

    impl<'a> Render<'a> {
        /// Apply the current effect stack to a style.
        /// Use this when you have a Style from a source other than the style
        /// manager.
        pub fn apply_effects(&self, style: Style) -> Style;

        /// Declare the cursor of this node at a location, in the coordinates of
        /// its other drawing.
        ///
        /// A cursor outside the visible view is not drawn. A node holds at most
        /// one cursor, so a later declaration replaces an earlier one. The
        /// cursor of the deepest node on the focus path is the primary cursor,
        /// which moves; every other cursor stays steady.
        pub fn cursor(&mut self, location: Point, request: CursorRequest);

        /// Fill a rectangle with a specified character. Writes out of bounds will
        /// be clipped.
        pub fn fill(&mut self, style: &str, r: Rect, c: char) -> crate::error::Result<()>;

        /// Push a style layer.
        pub fn push_layer(&mut self, name: &str);

        /// Write a single cell with a resolved style.
        pub fn put_cell(
            &mut self,
            style: ResolvedStyle,
            p: Point,
            ch: char,
        ) -> crate::error::Result<()>;

        /// Write a single antialiased cell: the named style, resolved at `p`
        /// within `rect`, with a glyph coverage applied. The cell moves when the
        /// style moves.
        pub fn put_covered(
            &mut self,
            style: &str,
            rect: Rect,
            p: Point,
            ch: char,
            coverage: Coverage,
        ) -> crate::error::Result<()>;

        /// Write a grapheme with a resolved style, including continuation cells.
        pub fn put_grapheme(
            &mut self,
            style: ResolvedStyle,
            p: Point,
            grapheme: &str,
        ) -> crate::error::Result<()>;

        /// Resolve a style by name and apply the current effect stack.
        pub fn resolve_style(&self, name: &str) -> Style;

        /// Apply a named style to the painted grapheme at a point, preserving its
        /// text.
        pub fn restyle(&mut self, style: &str, point: Point);

        /// Paint styled runs left to right from the start of `l`, clipped to it.
        ///
        /// Each run is a style path and its text. A run takes its foreground from
        /// its path and its background and attributes from `base`, so runs keep
        /// the ground of the row they sit on. Return the columns painted.
        pub fn runs<'r>(
            &mut self,
            l: Line,
            base: &str,
            runs: impl IntoIterator<Item = (&'r str, &'r str)>,
        ) -> crate::error::Result<u32>;

        /// Print text in the specified line. If the text is wider than the
        /// rectangle, it will be truncated; if it is shorter, it will be padded.
        pub fn text(&mut self, style: &str, l: Line, txt: &str) -> crate::error::Result<()>;
    }

    /// Limits for a materialized visible render target.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct RenderLimits {
        /// Maximum visible render-target width.
        pub max_width: u32,
        /// Maximum visible render-target height.
        pub max_height: u32,
        /// Maximum total number of materialized terminal cells.
        pub max_cells: usize,
    }

    impl RenderLimits {
        /// Validate a visible target size and return its exact cell count.
        pub fn cell_count(self, size: Size) -> crate::error::Result<usize>;

        /// Construct explicit visible render-target limits.
        pub const fn new(max_width: u32, max_height: u32, max_cells: usize) -> Self;
    }

    /// A 2D terminal buffer of styled cells.
    #[derive(Clone, Debug, PartialEq)]
    pub struct TermBuf {/* private fields */}

    impl TermBuf {
        /// Return the cells in row-major order.
        pub fn cells(&self) -> &[Cell];

        /// Emit this terminal buffer in full to the provided backend,
        /// batching runs of text with the same style. The caller flushes the
        /// backend.
        pub fn emit<R: RenderBackend>(&self, backend: &mut R) -> crate::error::Result<()>;

        /// Diff this terminal buffer against a previous state, emitting changes
        /// to the provided render backend. The caller flushes the backend.
        pub fn emit_diff<R: RenderBackend>(
            &self,
            prev: &Self,
            backend: &mut R,
        ) -> crate::error::Result<()>;

        /// Fill a rectangle with a glyph and style.
        pub fn fill(
            &mut self,
            style: &ResolvedStyle,
            r: Rect,
            ch: char,
        ) -> crate::error::Result<()>;

        /// Get a cell by position.
        pub fn get(&self, p: Point) -> Option<&Cell>;

        /// Construct a buffer filled with the given character and style.
        pub fn new(
            size: impl Into<Size>,
            ch: char,
            style: ResolvedStyle,
        ) -> crate::error::Result<Self>;

        /// Return the buffer bounds as a rectangle.
        pub fn rect(&self) -> Rect;

        /// Return the rendered screen as rows of cell strings.
        pub fn rows(&self) -> Vec<Vec<String>>;

        /// Return the rendered screen as newline-joined plain text.
        pub fn screen_text(&self) -> String;

        /// Return the buffer size.
        pub fn size(&self) -> Size;

        /// Draw text clipped to the given line.
        pub fn text(
            &mut self,
            style: &ResolvedStyle,
            l: Line,
            txt: &str,
        ) -> crate::error::Result<()>;
    }

    pub mod cursor {
        //! Cursor and position helpers.
        //! Soft cursors: roles, looks, and the declarations widgets make while they
        //! render.
        //!
        //! A widget names what its cursor means with a role, such as
        //! `cursor/vi/insert`. The theme decides how each role looks: a shape that
        //! Canopy draws exactly on every cell, a color, and a motion.

        /// How long a blinking cursor hides.
        pub const BLINK_OFF: Duration = _;

        /// How long a blinking cursor shows.
        pub const BLINK_ON: Duration = _;

        /// The root cursor role, which every other role falls back to.
        pub const CURSOR: &str = "cursor";

        /// Where typing lands in a field that is active without focus.
        pub const INACTIVE: &str = "cursor/inactive";

        /// One period of a pulsing cursor.
        pub const PULSE_PERIOD: Duration = _;

        /// The cursor of a program that runs in an embedded terminal.
        pub const TERMINAL: &str = "cursor/terminal";

        /// The cursor of editable text outside vi modes.
        pub const TEXT: &str = "cursor/text";

        /// The cursor of vi insert mode.
        pub const VI_INSERT: &str = "cursor/vi/insert";

        /// The cursor of vi normal mode.
        pub const VI_NORMAL: &str = "cursor/vi/normal";

        /// The cursor of vi visual mode.
        pub const VI_VISUAL: &str = "cursor/vi/visual";

        /// How a cursor role looks.
        #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
        pub struct CursorLook {
            /// Shape of the cursor.
            pub shape: CursorShape,
            /// Color of the cursor.
            pub color: Color,
            /// Change of the cursor over time.
            pub motion: CursorMotion,
        }

        impl CursorLook {
            /// A blinking block in `color`.
            pub const fn blinking_block(color: Color) -> Self;

            /// Construct a look.
            pub const fn new(shape: CursorShape, color: Color, motion: CursorMotion) -> Self;

            /// A steady block in `color`.
            pub const fn steady_block(color: Color) -> Self;
        }

        /// A replacement for parts of a role's look, kept across theme switches.
        #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
        pub struct CursorLookPatch {
            /// Replacement shape.
            pub shape: Option<CursorShape>,
            /// Replacement color.
            pub color: Option<Color>,
            /// Replacement motion.
            pub motion: Option<CursorMotion>,
        }

        /// The look of each cursor role.
        ///
        /// A role resolves with the fallback of style paths: `cursor/vi/insert` falls
        /// back to `cursor/vi`, then to `cursor`.
        #[derive(Clone, Debug, Default, PartialEq)]
        pub struct CursorLooks {/* private fields */}

        impl CursorLooks {
            /// Return the built-in looks for a palette.
            pub fn for_palette(p: &Palette) -> Self;

            /// Return the look set for exactly this role, without fallback.
            pub fn get(&self, role: &str) -> Option<CursorLook>;

            /// Resolve the look of a role, falling back to its parent roles.
            pub fn resolve(&self, role: &str) -> CursorLook;

            /// Set the look of a role.
            pub fn set(&mut self, role: &str, look: CursorLook);
        }

        /// How a cursor changes over time.
        #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
        pub enum CursorMotion {
            /// Always shown.
            Steady,
            /// Shown for `on`, then the cell below for `off`.
            Blink {
                /// Time the cursor shows.
                on: Duration,
                /// Time the cell below shows.
                off: Duration,
            },
            /// Fades between the cursor color and the cell below over one period.
            Pulse {
                /// Time of one fade out and back.
                period: Duration,
            },
        }

        impl CursorMotion {
            /// The default blink.
            pub const BLINK: Self = _;
            /// The default pulse.
            pub const PULSE: Self = _;
        }

        /// A cursor that a widget declares while it renders.
        #[derive(Clone, Debug, Eq, PartialEq)]
        pub struct CursorRequest {
            /// Role of the cursor.
            pub role: Cow<'static, str>,
            /// A color that replaces the color of the role, such as the cursor color
            /// that a child terminal program sets.
            pub color: Option<Color>,
            /// A motion that replaces the motion of the role.
            pub motion: Option<CursorMotion>,
            /// A shape that replaces the shape of the role.
            pub shape: Option<CursorShape>,
        }

        impl CursorRequest {
            /// Request a cursor in `role`, with the look of the role.
            pub fn new(role: impl Into<Cow<'static, str>>) -> Self;

            /// Replace the color of the role.
            #[must_use]
            pub fn with_color(self, color: Color) -> Self;

            /// Replace the motion of the role.
            #[must_use]
            pub fn with_motion(self, motion: CursorMotion) -> Self;

            /// Replace the shape of the role.
            #[must_use]
            pub fn with_shape(self, shape: CursorShape) -> Self;
        }

        /// A cursor shape that Canopy draws exactly on every cell.
        #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
        pub enum CursorShape {
            /// The whole cell takes the cursor color, and the grapheme takes a
            /// contrasting color.
            Block,
            /// The grapheme and its underline take the cursor color.
            Underline,
        }

        /// One cursor in a published frame.
        #[derive(Clone, Debug, Eq, PartialEq)]
        pub struct CursorSnapshot {
            /// Node that declared the cursor.
            pub node: NodeId,
            /// Screen location of the cursor.
            pub location: Point,
            /// Role of the cursor.
            pub role: String,
            /// Look the frame painted, after request replacements and style effects.
            pub look: CursorLook,
            /// Whether this is the primary cursor: the declaration of the deepest node
            /// on the focus path.
            pub primary: bool,
        }
    }
}

pub mod runtime {
    //! The runtime: turns, published frames, polls and wakes, and notices.

    /// Identifier of an immutable publication.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct FrameId(pub u64);

    /// Immutable data from one successfully prepared frame.
    #[derive(Clone, Debug, PartialEq)]
    pub struct FrameSnapshot {
        /// Publication generation shared with turn outcomes.
        pub frame_id: FrameId,
        /// The rendered frame buffer, shared with the backend emitter.
        pub buffer: Arc<TermBuf>,
        /// All live arena nodes, including detached trees.
        pub nodes: Vec<NodeSnapshot>,
        /// Focus owner at publication.
        pub focus: Option<NodeId>,
        /// Cursors the frame painted, the primary cursor first.
        pub cursors: Vec<CursorSnapshot>,
    }

    impl FrameSnapshot {
        /// Return the screen size: the dimensions of the rendered buffer.
        pub fn size(&self) -> Size;
    }

    /// Owned identity, geometry, and semantics for one live arena node.
    #[derive(Clone, Debug, PartialEq)]
    pub struct NodeSnapshot {
        /// Arena identity at publication, retained even after removal.
        pub id: NodeId,
        /// Structural parent at publication.
        pub parent: Option<NodeId>,
        /// Children in source order.
        pub children: Vec<NodeId>,
        /// Widget path name.
        pub name: String,
        /// Explicit application identity.
        pub identity: Option<NodeIdentity>,
        /// Whether the root tree contains this node.
        pub attached: bool,
        /// Attached with no hidden ancestor.
        pub displayed: bool,
        /// Intersection with the viewport and all ancestor content clips.
        pub intersects_viewport: bool,
        /// Current view geometry, absent when not displayed.
        pub view: Option<View>,
        /// Whether this node owns focus.
        pub focused: bool,
        /// Widget-provided observations captured after paint.
        pub semantics: WidgetSemantics,
    }

    /// Thread-safe handle that requests a poll of one widget incarnation.
    ///
    /// Producers keep results in their own bounded channels. This handle never owns
    /// the application or widget and expires when its registered lifetime ends.
    #[derive(Clone, Debug)]
    pub struct NodeWakeHandle {/* private fields */}

    impl NodeWakeHandle {
        /// Queue one owner poll, coalesce with existing work, or report expiration.
        pub fn wake(&self) -> crate::error::Result<WakeOutcome>;
    }

    /// A recoverable failure, reported to the user and to scripts.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct Notice {
        /// Human-readable failure message.
        pub message: String,
        /// Stable failure category, as script error payloads report it.
        pub kind: ScriptErrorKind,
        /// Where the failure arose.
        pub source: NoticeSource,
        /// Node the binding, handler, or poll ran on, when known.
        pub node: Option<NodeId>,
    }

    /// Where a notice arose.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum NoticeSource {
        /// A binding's command or callback failed.
        Binding,
        /// A widget's event or intent handler failed, or a call a widget posted.
        Widget,
        /// A widget's poll failed.
        Poll,
    }

    impl NoticeSource {
        /// Return a stable scripting and diagnostic label.
        pub fn label(self) -> &'static str;
    }

    /// Lifetime of runtime-managed widget work.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum PollLifetime {
        /// Continue while the widget exists, including while hidden or detached.
        #[default]
        Node,
        /// End when the widget is detached, replaced, or removed.
        Attachment,
    }

    /// One runtime input.
    pub enum TurnInput {
        /// Deliver input events that arrived together, in order.
        ///
        /// The turn dispatches each event and prepares one frame for the batch, so
        /// a burst of input costs one render. Layout settles before a mouse event
        /// that follows another event, so hit testing sees the geometry the earlier
        /// events left. Dispatch stops at the first error or exit request.
        Events(Vec<Event>),
        /// Service ready background work.
        Wake,
        /// Start a top-level evaluation.
        StartEval(EvalRequest),
        /// Cancel an evaluation owned by this runtime.
        CancelEval(EvalId),
        /// Prepare changes made through native access.
        Prepare,
    }

    /// Observable effects of one turn.
    #[derive(Default)]
    pub struct TurnOutcome {
        /// Frame published by this turn, if any.
        pub frame: Option<FrameId>,
        /// Whether moving cells changed without a new frame, so the adapter
        /// emits again.
        pub motion: bool,
        /// Evaluation accepted by this turn.
        pub started: Option<EvalId>,
        /// Evaluations completed after publication without an automation ticket.
        pub completed: Vec<EvalOutcome>,
        /// Requested application exit status.
        pub exit_code: Option<i32>,
    }

    /// Result of requesting a poll through a node wake handle.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum WakeOutcome {
        /// The owner now has pending work.
        Queued,
        /// The owner already had pending work.
        Coalesced,
        /// The owning widget, attachment, or application no longer exists.
        Expired,
    }

    /// Sending half of a bounded channel that polls its owner on every send.
    ///
    /// A background producer sends results here, and the owning widget drains
    /// the receiver from `Widget::poll`. The owner needs no polling interval while
    /// it waits: each successful send queues one coalesced poll.
    #[derive(Clone, Debug)]
    pub struct WakeSender<T> {/* private fields */}

    impl<T> WakeSender<T> {
        /// Send `value`, blocking while the channel is full, then poll the owner.
        ///
        /// Fails only when the receiver is gone. A wake that finds its owner
        /// expired is not an error: nobody is left to read the value.
        pub fn send(&self, value: T) -> Result<(), SendError<T>>;

        /// Send `value` without blocking, then poll the owner.
        pub fn try_send(&self, value: T) -> Result<(), TrySendError<T>>;
    }

    /// Optional application observations, without arbitrary widget serialization.
    #[derive(Clone, Debug, Default, PartialEq)]
    pub struct WidgetSemantics {
        /// Application role independent of structural wrappers.
        pub role: Option<String>,
        /// Human-readable accessible label.
        pub label: Option<String>,
        /// Explicitly exposed value; sensitive values must be omitted.
        pub value: Option<String>,
        /// Whether this widget is selected, when applicable.
        pub selected: Option<bool>,
        /// Stable application keys under a collection's selection cursor.
        pub selected_keys: Vec<ArgValue>,
        /// Stable application keys a collection has checked, in display order.
        pub checked_keys: Vec<ArgValue>,
        /// Availability of the widget's activation command.
        pub activation_status: Option<CommandStatus>,
    }

    /// Create a bounded channel whose sends poll the owner of `handle`.
    ///
    /// `capacity` bounds the values in flight; a full channel blocks `send`
    /// and fails `try_send`.
    pub fn wake_channel<T>(
        handle: NodeWakeHandle,
        capacity: usize,
    ) -> (WakeSender<T>, std::sync::mpsc::Receiver<T>);
}

#[expect(
    clippy::multiple_inherent_impl,
    reason = "LuauHost methods are split by compilation and detached invocation concerns."
)]
pub mod script {
    //! Scripting support.

    /// Base `canopy` scripting API declarations and native registration.
    pub type AutomationCallback = Box<dyn FnOnce(&mut Canopy) + Send + 'static>;

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone)]
    pub struct AutomationHandle {/* private fields */}

    impl AutomationHandle {
        /// Execute a closure on the UI thread and wait for its result.
        pub fn request<R, F>(&self, callback: F) -> crate::error::Result<R>
        where
            F: 'static + FnOnce(&mut Canopy) -> crate::error::Result<R> + Send,
            R: 'static + Send;

        /// Queue a callback to run on the UI thread.
        pub fn submit(&self, callback: AutomationCallback) -> crate::error::Result<()>;
    }

    impl AutomationHandle {
        /// Submit evaluation work without blocking the UI thread while it runs.
        pub fn submit_eval(&self, request: EvalRequest) -> crate::error::Result<EvalTicket>;
    }

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub struct EvalId(pub u64);

    /// Base `canopy` scripting API declarations and native registration.
    pub struct EvalOutcome {
        /// Evaluation that completed.
        pub id: EvalId,
        /// Completion value or failure.
        pub result: crate::error::Result<ArgValue>,
        /// Output isolated to this evaluation.
        pub logs: Vec<String>,
        /// Assertions isolated to this evaluation.
        pub assertions: Vec<ScriptAssertion>,
        /// Typecheck diagnostics for the source. A source that failed to
        /// typecheck never ran, and its result is the parse error.
        pub diagnostics: Vec<ScriptCheckDiagnostic>,
    }

    impl EvalOutcome {
        /// Return the evaluation result.
        pub fn into_result(self) -> crate::error::Result<ArgValue>;
    }

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone, Debug)]
    pub struct EvalRequest {
        /// Owned Luau source.
        pub source: String,
        /// Absolute execution budget, including parked time.
        pub timeout: Option<Duration>,
    }

    impl EvalRequest {
        /// Request an evaluation of `source` with no timeout.
        pub fn new(source: impl Into<String>) -> Self;

        /// Bound the evaluation, including parked time, by `timeout`.
        #[must_use]
        pub fn timeout(self, timeout: Duration) -> Self;
    }

    /// Base `canopy` scripting API declarations and native registration.
    pub struct EvalTicket {
        /// Accepted queue identity, including failed admission results.
        pub id: EvalId,
        /// Evaluation completion after publication.
        pub completion: futures_channel::oneshot::Receiver<EvalOutcome>,
    }

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone)]
    pub struct Fixture {
        /// Fixture name.
        pub name: String,
        /// Human-readable fixture description.
        pub description: String,
        /* private fields */
    }

    impl Fixture {
        /// Return fixture metadata without the setup closure.
        pub fn info(&self) -> FixtureInfo;

        /// Construct a fixture from owned name/description values.
        pub fn new(
            name: impl Into<String>,
            description: impl Into<String>,
            setup: impl 'static + Fn(&mut Canopy) -> crate::error::Result<()> + Send + Sync,
        ) -> Self;
    }

    /// Base `canopy` scripting API declarations and native registration.
#[derive(Clone, Debug, Deserialize<'de>, Eq, PartialEq, Serialize)]
    pub struct FixtureInfo {
        /// Fixture name.
        pub name: String,
        /// Human-readable fixture description.
        pub description: String,
    }

    impl JsonSchema for FixtureInfo {}

    /// Stable handle for a stored Luau closure.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub struct LuauFunctionId(_);

    /// Recorded assertion outcome for a script evaluation.
#[derive(Clone, Debug, Deserialize<'de>, Eq, PartialEq, Serialize)]
    pub struct ScriptAssertion {
        /// Whether the assertion passed.
        pub passed: bool,
        /// Assertion message or fallback description.
        pub message: String,
    }

    impl JsonSchema for ScriptAssertion {}

    /// Structured Luau typecheck diagnostic.
#[derive(Clone, Debug, Deserialize<'de>, Display, Eq, PartialEq, Serialize)]
    pub struct ScriptCheckDiagnostic {
        /// Diagnostic source name, when the diagnostic belongs to a named source.
        pub source: Option<String>,
        /// Diagnostic severity.
        pub severity: ScriptCheckSeverity,
        /// One-based line number, or zero when the diagnostic is not source-bound.
        pub line: usize,
        /// One-based column number, or zero when the diagnostic is not
        /// source-bound.
        pub column: usize,
        /// Human-readable diagnostic message.
        pub message: String,
    }

    impl ScriptCheckDiagnostic {
        /// Return true if this diagnostic should fail script evaluation.
        pub fn is_error(&self) -> bool;
    }

    impl JsonSchema for ScriptCheckDiagnostic {}

    /// Stable result returned by Luau typechecking APIs.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct ScriptCheckResult {/* private fields */}

    impl ScriptCheckResult {
        /// Return all diagnostics.
        pub fn diagnostics(&self) -> &[ScriptCheckDiagnostic];

        /// Render the failing diagnostics one per line.
        pub fn format_diagnostics(&self) -> String;

        /// Return true when the result contains failing diagnostics.
        pub fn has_errors(&self) -> bool;

        /// Consume the result and return its diagnostics.
        pub fn into_diagnostics(self) -> Vec<ScriptCheckDiagnostic>;
    }

    /// Severity of a checked Luau source diagnostic.
#[derive(Clone, Copy, Debug, Deserialize<'de>, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
    pub enum ScriptCheckSeverity {
        /// The diagnostic fails script evaluation.
        Error,
        /// The diagnostic does not fail script evaluation.
        Warning,
    }

    impl JsonSchema for ScriptCheckSeverity {}

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone, Debug)]
    pub struct ScriptJournalEntry {
        /// Monotonic journal id.
        pub id: u64,
        /// Where the source came from.
        pub origin: ScriptOrigin,
        /// Evaluated source text.
        pub source: String,
        /// Whether the evaluation completed successfully.
        pub ok: bool,
        /// Error message when `ok` is false.
        pub error: Option<String>,
        /// Logs emitted by the script.
        pub logs: Vec<String>,
        /// Assertions emitted by the script.
        pub assertions: Vec<ScriptAssertion>,
        /// Wall-clock duration in milliseconds.
        pub duration_ms: u64,
    }

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone, Debug, Display, Eq, PartialEq)]
    pub enum ScriptOrigin {
        /// Top-level application evaluation.
        Eval,
        /// A builder script file loaded from a path.
        ScriptFile(String),
        /// Application or mounted startup source.
        Startup(String),
        /// A named builder script.
        Build(String),
        /// Widget default-binding source.
        DefaultBindings(String),
    }

    /// Base `canopy` scripting API declarations and native registration.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum ScriptTrust {
        /// Do not mount, inspect, require, or execute this root.
        #[default]
        Disabled,
        /// Execute local scripts with the application's full native authority.
        TrustedLocal,
    }
}

pub mod style {
    //! Styling and color helpers.

    /// Colors over time: stops over one run, a run length, and a repeat.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Animation {
        /// Colors over one run, as gradient stops are colors over space.
        pub stops: Vec<GradientStop>,
        /// Length of one run.
        pub duration: Duration,
        /// What follows one run.
        pub repeat: Repeat,
        /// How time maps to the stops.
        pub easing: Easing,
        /// When the first run starts.
        pub start: AnimationStart,
        /// The space that mixes colors between stops.
        pub mix: Mix,
        /* private fields */
    }

    impl Animation {
        /// Show `on` for `on_time`, then `off` for `off_time`, in a loop.
        pub fn blink(on: Color, off: Color, on_time: Duration, off_time: Duration) -> Self;

        /// Fade once from `from` to `to`, from the first frame that shows it.
        pub fn fade(from: Color, to: Color, duration: Duration) -> Self;

        /// Map every stop color, keeping the timing and the bound start.
        #[must_use]
        pub fn map_colors(&self, f: impl Fn(Color) -> Color) -> Self;

        /// Construct a linear loop over `stops`, in step with the motion epoch.
        pub fn new(stops: Vec<GradientStop>, duration: Duration) -> Self;

        /// Fade from `from` to `to` and back, once each period.
        pub fn pulse(from: Color, to: Color, period: Duration) -> Self;

        /// Return the color that frames show at rest: the last stop of a single
        /// run, and the first stop of a repeating one.
        pub fn rest(&self) -> Color;

        /// Replace the easing.
        #[must_use]
        pub fn with_easing(self, easing: Easing) -> Self;

        /// Replace the mixing space.
        #[must_use]
        pub fn with_mix(self, mix: Mix) -> Self;

        /// Replace the repeat.
        #[must_use]
        pub fn with_repeat(self, repeat: Repeat) -> Self;

        /// Replace the start.
        #[must_use]
        pub fn with_start(self, start: AnimationStart) -> Self;
    }

    /// When the first run of an animation starts.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub enum AnimationStart {
        /// The shared motion epoch, which keeps loops in step with each other.
        Epoch,
        /// A fixed time on the driver clock.
        At(Instant),
        /// The last input event, so the motion restarts whenever the operator acts.
        LastInput,
        /// The first published frame that shows the animation. Clones share the
        /// bound time, so a paint that renders again keeps its start.
        Shown,
    }

    /// A text attribute.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum Attr {
        /// Bold text.
        Bold,
        /// Crossed out text.
        CrossedOut,
        /// Dim text.
        Dim,
        /// Italic text.
        Italic,
        /// Overlined text.
        Overline,
        /// Underlined text.
        Underline,
    }

    /// A set of active text attributes.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct AttrSet {
        /// Bold flag.
        pub bold: bool,
        /// Crossed out flag.
        pub crossedout: bool,
        /// Dim flag.
        pub dim: bool,
        /// Italic flag.
        pub italic: bool,
        /// Overline flag.
        pub overline: bool,
        /// Underline flag.
        pub underline: bool,
    }

    impl AttrSet {
        /// Construct a set of text attributes with a single attribute turned on.
        pub fn new(attr: Attr) -> Self;

        /// A helper for progressive construction of attribute sets.
        #[must_use]
        pub fn with(self, attr: Attr) -> Self;
    }

    /// A terminal color value.
    #[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
    pub enum Color {
        /// Black.
        Black,
        /// Dark grey.
        DarkGrey,
        /// Red.
        Red,
        /// Dark red.
        DarkRed,
        /// Green.
        Green,
        /// Dark green.
        DarkGreen,
        /// Yellow.
        Yellow,
        /// Dark yellow.
        DarkYellow,
        /// Blue.
        Blue,
        /// Dark blue.
        DarkBlue,
        /// Magenta.
        Magenta,
        /// Dark magenta.
        DarkMagenta,
        /// Cyan.
        Cyan,
        /// Dark cyan.
        DarkCyan,
        /// White.
        White,
        /// Grey.
        Grey,
        /// RGB color.
        Rgb {
            /// Red channel.
            r: u8,
            /// Green channel.
            g: u8,
            /// Blue channel.
            b: u8,
        },
        /// An ANSI color. See [256 colors - cheat
        /// sheet](https://jonasjacek.github.io/colors/) for more info.
        AnsiValue(u8),
    }

    impl Color {
        /// Return the WCAG contrast ratio with another color, from 1.0 for equal
        /// luminance to 21.0 for black on white.
        pub fn contrast_ratio(self, other: Self) -> f32;

        /// Invert RGB channels (255 - value for each channel).
        #[must_use]
        pub fn invert_rgb(self) -> Self;

        /// Mix this color with another in a color space. `t` 0.0 is `self`, and
        /// 1.0 is `other`.
        ///
        /// `Mix::Rgb` mixes the sRGB channels. `Mix::Oklab` mixes in the
        /// perceptual OKLab space, so equal steps look equal. `Mix::Oklch` also
        /// takes the shorter way around the hue circle.
        #[must_use]
        pub fn mix(self, other: Self, t: f32, space: Mix) -> Self;

        /// Return the WCAG relative luminance, from 0.0 for black to 1.0 for
        /// white.
        pub fn relative_luminance(self) -> f32;

        /// Return this color's RGB channels.
        ///
        /// Named colors and ANSI-256 values use the standard palette mappings.
        pub fn rgb(self) -> (u8, u8, u8);

        /// Adjust saturation. 0.0 = grayscale, 1.0 = unchanged, 2.0 = double
        /// saturation.
        #[must_use]
        pub fn saturation(self, factor: f32) -> Self;

        /// Scale brightness by a factor. 0.0 = black, 1.0 = unchanged, 2.0 = double
        /// brightness.
        #[must_use]
        pub fn scale_brightness(self, factor: f32) -> Self;

        /// Shift hue by degrees (0-360).
        #[must_use]
        pub fn shift_hue(self, degrees: f32) -> Self;
    }

    /// How much of a cell a glyph covers, for antialiased drawing.
    ///
    /// A covered cell mixes its style's background toward its foreground: by
    /// `fg` for the glyph and by `bg` for the cell ground, each 0 to 255.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub struct Coverage {
        /// Glyph coverage.
        pub fg: u8,
        /// Ground coverage.
        pub bg: u8,
    }

    impl Coverage {
        /// Apply the coverage to a resolved style.
        pub fn apply(self, style: ResolvedStyle) -> ResolvedStyle;
    }

    /// How time within a run maps to the stops.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub enum Easing {
        /// Colors change at a constant rate.
        Linear,
        /// Colors change slowly at the ends of a run and quickly in the middle.
        InOut,
        /// Each stop holds until the next one, with no mixing.
        Hold,
    }

    /// A gradient paint specification.
    #[derive(Clone, Debug, PartialEq)]
    pub struct GradientSpec {
        /// Gradient angle in degrees (0 = left to right, 90 = top to bottom).
        pub angle_deg: f32,
        /// Ordered list of gradient stops.
        pub stops: Vec<GradientStop>,
        /// The space that mixes colors between stops.
        pub mix: Mix,
        /// Time in which the gradient slides once across its rectangle, wrapping
        /// around. `None` holds it still.
        pub drift: Option<Duration>,
    }

    impl GradientSpec {
        /// Resolve a gradient color at a point within a rectangle, at rest.
        pub fn color_at(&self, rect: Rect, point: Point) -> Color;

        /// Map all colors in this gradient through a transform.
        #[must_use]
        pub fn map_colors(&self, f: impl Fn(Color) -> Color) -> Self;

        /// Slide the gradient once across its rectangle in each `period`.
        #[must_use]
        pub fn with_drift(self, period: Duration) -> Self;

        /// Replace the mixing space.
        #[must_use]
        pub fn with_mix(self, mix: Mix) -> Self;

        /// Construct a gradient from explicit stops.
        pub fn with_stops(angle_deg: f32, stops: Vec<GradientStop>) -> Self;
    }

    /// A gradient stop in a paint specification.
    #[derive(Clone, Debug, PartialEq)]
    pub struct GradientStop {
        /// Offset along the gradient (0.0-1.0).
        pub offset: f32,
        /// Color at this stop.
        pub color: Color,
    }

    impl GradientStop {
        /// Construct a gradient stop, clamping the offset to 0.0-1.0.
        pub fn new(offset: f32, color: Color) -> Self;
    }

    /// The space in which two colors mix.
    #[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq)]
    pub enum Mix {
        /// The sRGB channels.
        Rgb,
        /// The perceptual OKLab space, where equal steps look equal.
        #[default]
        Oklab,
        /// OKLab in polar form, which takes the shorter way around the hue circle.
        Oklch,
    }

    /// A paint definition for a style channel.
    #[derive(Clone, Debug, PartialEq)]
    pub enum Paint {
        /// Solid color fill.
        Solid(Color),
        /// Gradient fill.
        Gradient(GradientSpec),
        /// A color that changes over time.
        Animated(Arc<Animation>),
    }

    impl Paint {
        /// Construct an animated paint.
        pub fn animated(animation: Animation) -> Self;

        /// Construct a gradient paint.
        pub fn gradient(spec: GradientSpec) -> Self;

        /// Map colors within this paint.
        #[must_use]
        pub fn map_colors(&self, f: impl Fn(Color) -> Color) -> Self;

        /// Return whether the paint changes over time.
        pub fn moves(&self) -> bool;

        /// Resolve the paint at a location, at rest.
        pub fn resolve(&self, rect: Rect, point: Point) -> Color;

        /// Construct a solid paint.
        pub fn solid(color: Color) -> Self;

        /// Return the solid color if this paint is solid.
        pub fn solid_color(&self) -> Option<Color>;
    }

    impl From<Animation> for Paint {}

    impl From<Color> for Paint {}

    impl From<GradientSpec> for Paint {}

    /// A possibly partial style specification, which is stored in a StyleManager.
    /// Partial styles are completely resolved during the style resolution process.
    #[derive(Clone, Debug, Default, PartialEq)]
    pub struct PartialStyle {
        /// Optional foreground paint.
        pub fg: Option<Paint>,
        /// Optional background paint.
        pub bg: Option<Paint>,
        /// Optional attributes.
        pub attrs: Option<AttrSet>,
    }

    impl PartialStyle {
        /// Add one attribute to the attributes set so far.
        #[must_use]
        pub fn attr(self, attr: Attr) -> Self;

        /// Set every attribute at once; an empty set stops attributes inheriting.
        #[must_use]
        pub fn attrs(self, attrs: AttrSet) -> Self;

        /// Set the background paint.
        #[must_use]
        pub fn bg(self, paint: impl Into<Paint>) -> Self;

        /// Set the foreground paint.
        #[must_use]
        pub fn fg(self, paint: impl Into<Paint>) -> Self;

        /// Create an empty partial style, which inherits every component.
        pub fn new() -> Self;
    }

    /// What follows one run of an animation.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub enum Repeat {
        /// One run, which then holds its last color.
        Once,
        /// Runs one after another, each from the first stop.
        Loop,
        /// Runs forward, then backward, then forward again.
        Alternate,
    }

    /// A resolved style specification stored in terminal buffers.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct ResolvedStyle {
        /// Foreground color.
        pub fg: Color,
        /// Background color.
        pub bg: Color,
        /// Text attributes.
        pub attrs: AttrSet,
    }

    impl ResolvedStyle {
        /// Construct a resolved style from components.
        pub fn new(fg: Color, bg: Color, attrs: AttrSet) -> Self;
    }

    /// A paint-based style specification.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Style {
        /// Foreground paint.
        pub fg: Paint,
        /// Background paint.
        pub bg: Paint,
        /// Text attributes.
        pub attrs: AttrSet,
    }

    impl Style {
        /// Return whether either paint changes over time.
        pub fn moves(&self) -> bool;

        /// Resolve the style at a location within a rectangle.
        pub fn resolve_at(&self, rect: Rect, point: Point) -> ResolvedStyle;

        /// Resolve the style to a solid variant if both paints are solid.
        pub fn resolve_solid(&self) -> Option<ResolvedStyle>;
    }

    /// Map of style paths to partial styles, keyed by canonical path.
    #[derive(Clone, Debug, Default)]
    pub struct StyleMap {/* private fields */}

    impl StyleMap {
        /// Iterate over every rule as its canonical path and partial style.
        ///
        /// Paths omit the leading `/`, so the root rule's path is empty. The order
        /// is unspecified.
        pub fn entries(&self) -> impl Iterator<Item = (&str, &PartialStyle)>;

        /// Construct a style map with defaults.
        pub fn new() -> Self;

        /// Resolve the style at `path`, as a widget with no pushed layers
        /// would see it.
        pub fn resolve(&self, path: &str) -> Style;

        /// Begin a fluent rule-building chain.
        ///
        /// # Example
        ///
        /// ```
        /// use canopy::style::{StyleMap, solarized};
        ///
        /// let mut style_map = StyleMap::new();
        /// style_map
        ///     .rules()
        ///     .fg("red/text", Color::Red)
        ///     .fg("blue/text", Color::Blue)
        ///     .apply();
        /// ```
        pub fn rules(&mut self) -> StyleRules<'_>;
    }

    /// A fluent builder for adding style rules to a StyleMap.
    ///
    /// Created via [`StyleMap::rules()`]. Collects path/style pairs and commits
    /// them on [`.apply()`](StyleRules::apply).
    #[must_use = "call .apply() to commit rules"]
    pub struct StyleRules<'a> {/* private fields */}

    impl<'a> StyleRules<'a> {
        /// Commit all pending rules to the StyleMap.
        pub fn apply(self);

        /// Add a single attribute for a path.
        ///
        /// If a rule already exists for this path, the attribute is merged
        /// with the existing style.
        pub fn attr(self, path: &str, attr: Attr) -> Self;

        /// Set the background paint for a path.
        ///
        /// If a rule already exists for this path, the background paint is merged
        /// with the existing style.
        pub fn bg(self, path: &str, paint: impl Into<Paint>) -> Self;

        /// Set the foreground paint for a path.
        ///
        /// If a rule already exists for this path, the foreground paint is merged
        /// with the existing style.
        pub fn fg(self, path: &str, paint: impl Into<Paint>) -> Self;

        /// Clear the current prefix.
        pub fn no_prefix(self) -> Self;

        /// Set a path prefix for all subsequent rules.
        ///
        /// Can be called multiple times; each call replaces the previous prefix.
        pub fn prefix(self, prefix: &str) -> Self;

        /// Apply a complete style to a path.
        ///
        /// If a rule already exists for this path, the style is merged
        /// with the existing style (new values take precedence).
        pub fn style(self, path: &str, style: impl Into<PartialStyle>) -> Self;

        /// Apply a complete style to multiple paths.
        ///
        /// If a rule already exists for any path, the style is merged
        /// with the existing style (new values take precedence).
        pub fn style_all(self, paths: &[&str], style: impl Into<PartialStyle>) -> Self;
    }

    /// Independent widget states mapped onto the existing style layer stack.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum WidgetState {
        /// The widget or its descendant holds focus.
        Focused,
        /// The widget is selected independently of focus.
        Selected,
        /// The widget's command is disabled.
        Disabled,
        /// The widget is pressed or explicitly active.
        Pressed,
    }

    impl WidgetState {
        /// Return the existing string layer for this state.
        pub const fn layer(self) -> &'static str;
    }

    /// Parse one hex byte from its two digits.
    ///
    /// This supports the [`rgb!`](crate::rgb) macro and is not part of the stable
    /// surface.
    #[doc(hidden)]
    pub const fn hex_byte(high: u8, low: u8) -> u8;

    pub mod animation {
        //! Colors that change over time.
        //!
        //! An [`Animation`] is to time what a gradient is to space: colors at stops
        //! over one run. Canopy renders every animation at rest, and evaluates it only
        //! when it emits cells to the terminal.

        pub use crate::style::{Animation, AnimationStart, Easing, Repeat};
    }

    pub mod effects {
        //! Style effects system.
        //! Style effects system for transforming styles during rendering.
        //!
        //! Effects are transformations applied to styles that inherit through the node
        //! tree. They can modify colors, attributes, or both.

        /// Brightness factor for what a modal covers, so a panel over the view reads
        /// apart from the dimmed view behind it.
        pub const MODAL_DIM: f32 = 0.5;

        /// Time a modal takes to dim what it covers.
        pub const MODAL_FADE: Duration = _;

        /// A style transformation that can be applied during rendering.
        ///
        /// Effects are stacked and applied in order during render traversal.
        /// They inherit through the tree unless explicitly cleared.
        pub trait StyleEffect: Debug + Send + Sync {
            /// Apply this effect to a style, returning the transformed style.
            fn apply(&self, style: Style) -> Style;
        }

        /// Shared handle for effects stored on nodes and stacked during rendering.
        pub type Effect = Arc<dyn StyleEffect>;

        /// Create an effect that adds bold attribute.
        pub fn bold() -> Effect;

        /// Create a brightness effect. Factor below 1.0 dims, above 1.0 brightens.
        pub fn brightness(factor: f32) -> Effect;

        /// Create a hue shift effect.
        pub fn hue_shift(degrees: f32) -> Effect;

        /// Create an effect that inverts RGB channels (255-value).
        pub fn invert_rgb() -> Effect;

        /// Create an effect that adds italic attribute.
        pub fn italic() -> Effect;

        /// Create the effect of what a modal covers: a fade to [`MODAL_DIM`] over
        /// [`MODAL_FADE`].
        pub fn modal_dim() -> Effect;

        /// Create a saturation effect. 0.0 = grayscale, 1.0 = unchanged.
        pub fn saturation(factor: f32) -> Effect;

        /// Create an effect that fades each color from its value to the value of
        /// `effect` over `duration`.
        ///
        /// The fade starts with the first frame that shows it, and frames at rest
        /// show the faded colors. Keep the returned effect for as long as it applies:
        /// a new transition fades again.
        pub fn transition(effect: Effect, duration: Duration) -> Effect;
    }

    pub mod roles {
        //! Shared part names that widgets paint beneath their own layer.
        //!
        //! A widget pushes its node name as a layer and paints these bare roles, so
        //! `button/text` and `input/text` are both the `TEXT` part.

        /// The ground a widget fills before painting its parts.
        pub const BACKGROUND: &str = "background";

        /// Box chrome drawn around a widget.
        pub const BORDER: &str = "border";

        /// A key name, such as an accelerator or a binding hint.
        pub const KEY: &str = "key";

        /// A fixed prompt before editable text.
        pub const PROMPT: &str = "prompt";

        /// Ordinary text.
        pub const TEXT: &str = "text";

        /// A scrollbar thumb.
        pub const THUMB: &str = "thumb";

        /// A title in a widget's chrome.
        pub const TITLE: &str = "title";

        /// Paint a retained selection according to which control takes the keys.
        /// Pass actual focus, or the composite widget's active part. Inactive
        /// selections remain visible without claiming keyboard focus.
        pub const fn selection(active: bool) -> &'static str;
    }

    pub mod themes {
        //! Built-in themes: role palettes and the one rule set they share.
        //!
        //! A theme is a [`Palette`] of role colours. [`Palette::style_map`] builds the
        //! rule set every built-in theme shares, so adding a rule here adds it to every
        //! theme at once. Applications style their own paths from the palette through
        //! `Setup::widget_styles`, which keeps those rules across theme switches.

        /// The role colours a theme assigns.
        ///
        /// Each field names the role a colour plays, not the colour itself, so the same
        /// rule set can render a light theme, a dark theme, or any other palette.
        #[derive(Clone, Copy, Debug)]
        pub struct Palette {
            /// Default foreground.
            pub fg: Color,
            /// Default background, and the foreground drawn on top of `accent`.
            pub bg: Color,
            /// Inactive frame borders.
            pub frame: Color,
            /// Border of the frame that holds focus.
            pub frame_focused: Color,
            /// Base colour of scrollbar thumbs, tinted toward the accent.
            pub frame_thumb: Color,
            /// Frame title text.
            pub frame_title: Color,
            /// Primary accent: focus and selection.
            pub accent: Color,
            /// Foreground on panel backgrounds, one step away from `fg`.
            pub muted_fg: Color,
            /// Quiet foreground a step below `muted_fg`: placeholders, gutters, and
            /// hints.
            pub faint_fg: Color,
            /// Background of panels such as the help overlay and prompt.
            pub panel_bg: Color,
            /// Background of raised elements set on a panel, such as inactive tabs.
            pub element_bg: Color,
            /// Selection background: editor selections and the active tab.
            pub selection_bg: Color,
            /// Editor line-number gutter.
            pub line_number: Color,
            /// Key names in the help overlay.
            pub key: Color,
            /// Named blue.
            pub blue: Color,
            /// Named red.
            pub red: Color,
            /// Named magenta.
            pub magenta: Color,
            /// Named violet.
            pub violet: Color,
            /// Named cyan.
            pub cyan: Color,
            /// Named green.
            pub green: Color,
            /// Named yellow, also the hue of search matches.
            pub yellow: Color,
            /// Named orange.
            pub orange: Color,
        }

        impl Palette {
            /// Build the shared rule set for this palette.
            pub fn style_map(&self) -> StyleMap;
        }

        /// The default theme: a neutral near-black ground, grey chrome, and a single
        /// accent.
        ///
        /// The grey ramp follows opencode's default theme, and the named colours come
        /// from the One Dark and TokyoNight families that opencode and Grok Build draw
        /// on.
        pub fn default_dark() -> Palette;

        /// The Dracula theme: <https://draculatheme.com>.
        pub fn dracula() -> Palette;

        /// The dark gruvbox theme by morhetz: <https://github.com/morhetz/gruvbox>.
        pub fn gruvbox_dark() -> Palette;

        /// The dark Solarized theme.
        pub fn solarized_dark() -> Palette;

        /// The light Solarized theme.
        pub fn solarized_light() -> Palette;
    }
}

pub mod terminal {
    //! Crossterm terminal run-loop integration.

    /// Hook that takes a Ctrl+C before the terminal adapter exits on it. It runs
    /// against the root context and returns whether it took the interrupt.
    pub type InterruptHook = fn(_: &mut dyn Context) -> crate::error::Result<bool>;

    /// Host handling of terminal Ctrl+C input.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum InterruptPolicy {
        /// Restore the terminal and exit the host loop with status 130.
        #[default]
        Exit130,
        /// Deliver Ctrl+C through normal application input routing.
        RouteToApplication,
    }

    /// Terminal adapter policy, applied before application input dispatch.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct RunOptions {
        /// Policy for Ctrl+C.
        pub interrupt_policy: InterruptPolicy,
        /// Optional exact key that exits even when Ctrl+C is routed.
        pub emergency_exit: Option<Key>,
        /// Whether an exit on Ctrl+C or the emergency key prints the node tree to
        /// standard error after it restores the terminal.
        pub interrupt_dump: bool,
    }

    /// Run the terminal adapter until the application requests an exit.
    ///
    /// `options` decides how Ctrl+C and the emergency exit key stop the loop. With
    /// the default options, Ctrl+C restores the terminal, dumps the node tree, and
    /// returns status 130. `RunOptions::interrupt_dump` turns the dump off, and an
    /// interrupt hook (`Setup::on_interrupt`) can take a Ctrl+C instead.
    /// Keyboard enhancement flags are enabled so escape codes are unambiguous.
    pub fn runloop(cnpy: Canopy, options: RunOptions) -> crate::error::Result<i32>;
}

pub mod text {
    //! Text utilities.

    /// Which end of a string a truncation drops when it does not fit.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum Truncate {
        /// Drop the tail, which is how ordinary text reads.
        #[default]
        End,
        /// Drop the head, which keeps the last components of a path visible.
        Start,
    }

    impl Truncate {
        /// Return `s` cut to `budget` columns at this end.
        pub fn apply(self, s: &str, budget: usize) -> Cow<'_, str>;
    }

    /// Return the cells one grapheme occupies at `column`, expanding a tab to the
    /// next multiple of `tab_stop`.
    pub fn cell_width(grapheme: &str, column: usize, tab_stop: usize) -> usize;

    /// Expand tabs into spaces using the configured tab stop.
    pub fn expand_tabs(s: &str, tab_stop: usize) -> Cow<'_, str>;

    /// Return the display width of a grapheme cluster, capped at terminal cell
    /// widths.
    pub fn grapheme_width(grapheme: &str) -> usize;

    /// Slice a string by display columns, returning the substring and its width.
    pub fn slice_by_columns(s: &str, start: usize, max: usize) -> (&str, usize);

    /// Return the marker and the kept tail that shorten `s` to `budget` display
    /// columns by dropping its head.
    ///
    /// The tail borrows from `s`, so a caller can tell where it starts, as a row
    /// that highlights characters of the whole text needs. Text that fits keeps
    /// no marker. A budget of one or two columns holds the marker alone, because
    /// a character beside it could be drawn over.
    #[must_use]
    pub fn split_start(s: &str, budget: usize) -> (&'static str, &str);

    /// Compute the width of the next tab from the provided column.
    pub fn tab_width(column: usize, tab_stop: usize) -> usize;

    /// Shorten `s` to `budget` display columns, marking a dropped tail.
    ///
    /// Text that already fits is returned as it is. This is the ordinary
    /// direction, for text whose opening identifies it. A blank cell separates
    /// the marker from the kept head, as [`split_start`] describes.
    pub fn truncate_end(s: &str, budget: usize) -> Cow<'_, str>;

    /// Shorten `s` to `budget` display columns, marking a dropped head.
    ///
    /// Text that already fits is returned as it is, so a caller pays nothing for
    /// the common case. The marker keeps the tail visible, which is what a long
    /// filesystem path needs: its last components identify it, and its leading
    /// ones repeat. See [`split_start`] for the marker.
    pub fn truncate_start(s: &str, budget: usize) -> Cow<'_, str>;

    /// Return the terminal cells `s` occupies, saturating at `u32::MAX`.
    ///
    /// This is the one width measure: layout, measurement, and painting agree on
    /// it because it counts grapheme widths as rendering does.
    pub fn width(s: &str) -> u32;
}

pub mod tree {
    //! Tree structure: slots, identities, and focus traversal.

    /// A typed slot for slots.
    ///
    /// This trait associates a string key with a specific widget type, providing
    /// compile-time type safety for keyed child access.
    ///
    /// Use the [`crate::slot!`] macro to define keys:
    ///
    /// ```
    /// use canopy::{ChildSlot, Widget, slot};
    ///
    /// pub struct Modal;
    /// impl Widget for Modal {}
    ///
    /// slot!(ModalSlot: Modal);
    /// assert_eq!(ModalSlot::KEY, "ModalSlot");
    /// ```
    // Not dyn-compatible.
    pub trait ChildSlot {
        /// The widget type associated with this key.
        type Widget: 'static + Widget;
        /// The string key used for storage.
        const KEY: &'static str;
    }

    /// Direction for focus movement.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum FocusDirection {
        /// Move to the next focusable node.
        Next,
        /// Move to the previous focusable node.
        Prev,
        /// Move focus up.
        Up,
        /// Move focus down.
        Down,
        /// Move focus left.
        Left,
        /// Move focus right.
        Right,
    }

    impl CommandType for FocusDirection {}

    impl FromArgValue for FocusDirection {}

    impl ToArgValue for FocusDirection {}

    /// Subtree used by a focus traversal operation.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum FocusScope {
        /// The current widget's subtree.
        Current,
        /// The complete widget tree.
        Root,
        /// A subtree rooted at an explicit node.
        Node(NodeId),
    }

    /// Application identity unique within an explicit arena subtree.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct NodeIdentity {
        /// Scope root, which may itself be detached.
        pub scope: NodeId,
        /// Application-defined key independent of structural slots.
        pub key: String,
    }
}
